Function pair <- JsonPair(name As String, stock As Integer)
  Define pair As String;
  pair <- '{"' + name + '": ' + toText(stock) + "}";
EndFunction

Algorithm Pair
  Define name As String;
  Define stock As Integer;
  Read name;
  Read stock;
  Write JsonPair(name, stock);
EndAlgorithm
